                res.append(String(curIP.dropLast()))
                return
            }
            if dots > 4 { return }

            for j in i..<min(i + 3, chars.count) {
                if i != j && chars[i] == "0" { continue }
                let part = String(chars[i...j])
                if let num = Int(part), num < 256 {
                    backtrack(j + 1, dots + 1, curIP + part + ".")
                }
            }
        }

        backtrack(0, 0, "")
        return res
