                res.Add(curIP.Substring(0, curIP.Length - 1));
                return;
            }
            if (dots > 4) return;

            for (int j = i; j < Math.Min(i + 3, s.Length); j++) {
                if (i != j && s[i] == '0') continue;
                string part = s.Substring(i, j - i + 1);
                if (int.Parse(part) < 256) {
                    Backtrack(j + 1, dots + 1, curIP + part + ".");
                }
            }
        }

        Backtrack(0, 0, "");
        return res;
    }
}

