class Solution {
    func restoreIpAddresses(_ s: String) -> [String] {
        var res: [String] = []
        if s.count > 12 {
            return res
        }

        backtrack(0, 0, "", s, &res)
        return res
    }

    private func backtrack(_ i: Int, _ dots: Int, _ curIP: String, _ s: String, _ res: inout [String]) {
        if dots == 4 && i == s.count {
            res.append(String(curIP.dropLast()))
            return
        }
        if dots > 4 {
            return
        }

        let chars = Array(s)
        for j in i..<min(i + 3, s.count) {
            if i != j && chars[i] == "0" {
                continue
            }
            let startIndex = s.index(s.startIndex, offsetBy: i)
            let endIndex = s.index(s.startIndex, offsetBy: j + 1)
            let substring = String(s[startIndex..<endIndex])
            if let num = Int(substring), num < 256 {
                backtrack(j + 1, dots + 1, curIP + substring + ".", s, &res)
            }
        }
